ALTER TABLE public.profiles ADD COLUMN phone text NOT NULL DEFAULT '', ADD COLUMN contact_email text NOT NULL DEFAULT '', ADD COLUMN address text NOT NULL DEFAULT '', ADD COLUMN bio text NOT NULL DEFAULT '';
CREATE POLICY admin_edit_profiles ON public.profiles FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.account_access (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), suspended boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.account_access TO authenticated; GRANT ALL ON public.account_access TO service_role; GRANT INSERT, UPDATE, DELETE ON public.account_access TO authenticated;
ALTER TABLE public.account_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_access ON public.account_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY manage_access ON public.account_access FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin') AND user_id<>auth.uid());
CREATE FUNCTION public.account_enabled(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.account_access WHERE user_id=_user_id AND suspended); $$;
CREATE OR REPLACE FUNCTION public.is_editor() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_enabled(auth.uid()) AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'editor')); $$;
CREATE POLICY enabled_news_writes ON public.news AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.account_enabled(auth.uid()));
CREATE POLICY delete_news ON public.news FOR DELETE TO authenticated USING(public.is_editor()); GRANT DELETE ON public.news TO authenticated;
CREATE TABLE public.app_content (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, name text NOT NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.app_content TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.app_content TO authenticated; GRANT ALL ON public.app_content TO service_role;
ALTER TABLE public.app_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_content ON public.app_content FOR SELECT TO anon,authenticated USING(active AND kind IN ('category','district','advertisement','live','bulletin'));
CREATE POLICY editor_content ON public.app_content FOR ALL TO authenticated USING(public.is_editor()) WITH CHECK(public.is_editor());
CREATE TABLE public.payment_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journalist_id uuid NOT NULL REFERENCES public.profiles(id), month text NOT NULL, amount numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'processing', note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.payment_records TO authenticated; GRANT ALL ON public.payment_records TO service_role;
ALTER TABLE public.payment_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_payments ON public.payment_records FOR SELECT TO authenticated USING(journalist_id=auth.uid());
CREATE POLICY admin_payments ON public.payment_records FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') AND public.account_enabled(auth.uid())) WITH CHECK(public.has_role(auth.uid(),'admin') AND public.account_enabled(auth.uid()));
CREATE POLICY enabled_clip_upload ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'news-clips' OR public.account_enabled(auth.uid()));